            test_params[param] = str(value) + payload
            try:
                response = requests.get(url, params=test_params, timeout=5)
                if any(err in response.text.lower() for err in ["sql", "syntax", "mysql", "sqlite", "oracle", "postgresql"]):
                    vulnerabilities.append(f"{param} med payload: {payload}")
                    break
            except requests.RequestException:
                pass

    return vulnerabilities
