import pyshark
import re
from collections import Counter
from math import log2

def calculate_entropy(s: str) -> float:
    return -sum((s.count(c) / len(s)) * log2(s.count(c) / len(s)) for c in set(s))

def analyze_dns_traffic(pcap_file: str) -> dict:
    cap = pyshark.FileCapture(pcap_file, display_filter='dns.flags.response == 0')
    stats = Counter()
    suspicious = set()

    for pkt in cap:
        try:
            qname = pkt.dns.qry_name.lower()
            stats[qname] += 1
            labels = qname.split('.')
            sld = labels[-2] if len(labels) >= 2 else qname

            if len(sld) > 15 and calculate_entropy(sld) > 3.5:
                suspicious.add(qname)
            elif len(qname) > 50:
                suspicious.add(qname)
            elif stats[qname] > 50:
                suspicious.add(qname)
        except AttributeError:
            continue

    cap.close()
    return {
        "suspicious_domains": list(suspicious),
        "total_queries": sum(stats.values()),
        "unique_domains": len(stats)
    }
```

